/**
 * Walks up from the start directory to find a .env file.
 * Works for ts-node (src/) and compiled output.
 * @param startDir - The directory to start searching from
 * @returns The path to the .env file, or null if not found
 */
export function findEnvFile(startDir: string): string | null {
  let dir = startDir;
  for (let i = 0; i < 10; i++) {
    const candidate = resolve(dir, '.env');
    if (existsSync(candidate)) return candidate;
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

export interface LoadEnvOptions {
  /** The service name for logging (e.g., 'guernsey', 'fr24') */
  serviceName: string;
  /** The directory to start searching from (defaults to __dirname) */
  startDir?: string;
  /** Whether to log the env file path when found */
  logPath?: boolean;
}

/**
 * Loads environment variables from a .env file found by walking up directories.
 * @param options - Configuration options for loading the env file
 */
export function loadEnv(options: LoadEnvOptions): void {
  const { serviceName, startDir = process.cwd(), logPath = false } = options;
  const envPath = findEnvFile(startDir);

  if (envPath) {
    config({ path: envPath });
    if (logPath) {
      console.log(`[${serviceName}] Loaded env from ${envPath}`);
    }
  } else {
    console.warn(`[${serviceName}] Warning: .env file not found, relying on environment variables`);
  }
}

/** Guernsey timezone - Europe/London (UTC+0 winter, UTC+1 summer/BST) */
export const GY_TZ = 'Europe/London';

/**
 * Returns the current hour (0-23) in Guernsey local time.
 * @param d - Date to get the hour for (defaults to now)
 * @returns Hour as a number (0-23)
 */
export function guernseyHour(d: Date = new Date()): number {
  return parseInt(
    new Intl.DateTimeFormat('en-GB', { timeZone: GY_TZ, hour: 'numeric', hour12: false }).format(d),
    10,
  );
}

/**
 * Returns the current date as YYYY-MM-DD in Guernsey local time.
 * @param d - Date to format (defaults to now)
 * @returns Date string in en-CA format (YYYY-MM-DD)
 */
export function guernseyDateStr(d: Date = new Date()): string {
  return new Intl.DateTimeFormat('en-CA', { timeZone: GY_TZ }).format(d);
}

/**
 * Returns tomorrow's date string (YYYY-MM-DD) in Guernsey local time.
 * Adds 1 day in UTC first, then converts — correctly handles BST boundary.
 * @returns Tomorrow's date as YYYY-MM-DD
 */
export function guernseyTomorrowStr(): string {
  const tomorrow = new Date();
  tomorrow.setUTCDate(tomorrow.getUTCDate() + 1);
  return new Intl.DateTimeFormat('en-CA', { timeZone: GY_TZ }).format(tomorrow);
}

/**
 * Returns the next UTC Date at which Guernsey local time will be `hour:minute`.
 * If that time today is already past, returns tomorrow's occurrence.
 * @param hour - Target hour (0-23)
 * @param minute - Target minute (0-59)
 * @returns The next UTC Date matching the specified Guernsey local time
 */
export function nextGuernseyTime(hour: number, minute: number): Date {
  const todayGY = guernseyDateStr();
  const pad = (n: number) => String(n).padStart(2, '0');
  const candidateStr = `${todayGY}T${pad(hour)}:${pad(minute)}:00`;

  const now = new Date();
  const nowGYStr = new Intl.DateTimeFormat('en-GB', {
    timeZone: GY_TZ,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
  }).format(now);

  // en-GB format: "DD/MM/YYYY, HH:MM:SS"
  const [datePart, timePart] = nowGYStr.split(', ');
  const [dd, mm, yyyy] = datePart.split('/');
  const gyWallNow = new Date(`${yyyy}-${mm}-${dd}T${timePart}Z`); // treat as UTC for arithmetic
  const offsetMs = now.getTime() - gyWallNow.getTime();

  const targetGYWall = new Date(`${candidateStr}Z`);
  let targetUTC = new Date(targetGYWall.getTime() + offsetMs);

  if (targetUTC <= now) {
    targetUTC = new Date(targetUTC.getTime() + 24 * 60 * 60 * 1000);
  }

  return targetUTC;
}

/** Statuses that indicate a flight has reached a terminal state */
export const TERMINAL_STATUSES = ['Landed', 'Cancelled', 'Completed', 'Diverted'] as const;

/** Type for terminal status values */
export type TerminalStatus = typeof TERMINAL_STATUSES[number];

/**
 * Checks if a flight status is terminal (flight is complete and no longer active).
 * Also checks for statuses that start with 'diverted' (case-insensitive).
 * @param status - The flight status to check
 * @returns True if the status is terminal
 */
export function isTerminalStatus(status: string | null | undefined): boolean {
  if (!status) return false;

  const normalizedStatus = status.toLowerCase();

  // Check for exact terminal status match
  if (TERMINAL_STATUSES.includes(status as TerminalStatus)) {
    return true;
  }

  // Check for diverted variants (e.g., "Diverted to XXX")
  if (normalizedStatus.startsWith('diverted')) {
    return true;
  }

  return false;
}

/**
 * Options for getActiveFlightsToday query building
 */
export interface ActiveFlightsOptions {
  /** The date string (YYYY-MM-DD) to query */
  date: string;
  /** Additional status values to treat as terminal (optional) */
  additionalTerminalStatuses?: string[];
}

/**
 * SQL condition builder options for active flights
 * Note: This returns the conditions that should be used in a WHERE clause.
 * The actual query building is left to the caller since they have access to the ORM.
 */
export interface ActiveFlightConditions {
  /** The flight date to match */
  date: string;
  /** Statuses that should be excluded (terminal statuses) */
  excludedStatuses: readonly string[];
  /** Whether to exclude cancelled flights */
  excludeCancelled: boolean;
}

/**
 * Returns the standard conditions for querying active flights.
 * @param options - Options including date and optional additional terminal statuses
 * @returns Conditions object for building the query
 */
export function getActiveFlightsConditions(options: ActiveFlightsOptions): ActiveFlightConditions {
  const { date, additionalTerminalStatuses = [] } = options;
  return {
    date,
    excludedStatuses: [...TERMINAL_STATUSES, ...additionalTerminalStatuses],
    excludeCancelled: true,
  };
}

/** Configuration options for the circuit breaker */
export interface CircuitBreakerConfig {
  /** Number of failures before opening the circuit (default: 5) */
  threshold: number;
  /** Time in milliseconds before attempting to reset (default: 60000) */
  resetTimeoutMs: number;
  /** Service name for logging */
  serviceName: string;
}

/** State of the circuit breaker */
export interface CircuitBreakerState {
  failures: number;
  lastFailureTime: number | null;
  isOpen: boolean;
}

/**
 * Circuit breaker pattern implementation for handling transient failures.
 * After a threshold of failures, the circuit opens and operations are skipped
 * until the reset timeout has passed.
 */
export class CircuitBreaker {
  private failures: number;
  private lastFailureTime: number | null;
  private isOpen: boolean;
  private readonly threshold: number;
  private readonly resetTimeoutMs: number;
  private readonly serviceName: string;

  constructor(config: CircuitBreakerConfig) {
    this.threshold = config.threshold;
    this.resetTimeoutMs = config.resetTimeoutMs;
    this.serviceName = config.serviceName;
    this.failures = 0;
    this.lastFailureTime = null;
    this.isOpen = false;
  }

  /**
   * Checks if the circuit breaker allows operations to proceed.
   * If the circuit is open but the reset timeout has passed, it will reset and allow.
   * @returns True if operations should proceed, false if they should be skipped
   */
  check(): boolean {
    if (this.isOpen) {
      const now = Date.now();
      if (this.lastFailureTime && now - this.lastFailureTime > this.resetTimeoutMs) {
        this.isOpen = false;
        this.failures = 0;
        console.log(`[${this.serviceName}] Circuit breaker reset, resuming operations`);
        return true;
      }
      console.log(`[${this.serviceName}] Circuit breaker is OPEN, skipping operation`);
      return false;
    }
    return true;
  }

  /**
   * Records a failure. If failures reach the threshold, the circuit opens.
   */
  recordFailure(): void {
    this.failures++;
    this.lastFailureTime = Date.now();
    if (this.failures >= this.threshold) {
      this.isOpen = true;
      console.error(`[${this.serviceName}] Circuit breaker OPENED after ${this.failures} failures`);
    }
  }

  /**
   * Records a success. Decrements the failure count (with a floor of 0).
   */
  recordSuccess(): void {
    if (this.failures > 0) {
      this.failures = Math.max(0, this.failures - 1);
    }
  }

  /**
   * Gets the current state of the circuit breaker.
   * @returns The current state
   */
  getState(): CircuitBreakerState {
    return {
      failures: this.failures,
      lastFailureTime: this.lastFailureTime,
      isOpen: this.isOpen,
    };
  }

  /**
   * Manually resets the circuit breaker to closed state.
   */
  reset(): void {
    this.isOpen = false;
    this.failures = 0;
    this.lastFailureTime = null;
    console.log(`[${this.serviceName}] Circuit breaker manually reset`);
  }
}

/**
 * Environment variable names for circuit breaker configuration
 */
export const CIRCUIT_BREAKER_ENV = {
  /** Environment variable for failure threshold */
  THRESHOLD: 'CIRCUIT_BREAKER_THRESHOLD',
  /** Environment variable for reset timeout in milliseconds */
  RESET_MS: 'CIRCUIT_BREAKER_RESET_MS',
  /** Environment variable for scraper-specific failure threshold */
  SCRAPER_THRESHOLD: 'SCRAPER_CIRCUIT_BREAKER_THRESHOLD',
  /** Environment variable for scraper-specific reset timeout */
  SCRAPER_RESET_MS: 'SCRAPER_CIRCUIT_BREAKER_RESET_MS',
} as const;

/**
 * Creates a CircuitBreaker instance from environment variables with defaults.
 * @param serviceName - The service name for logging
 * @param defaultThreshold - Default failure threshold (default: 5)
 * @param defaultResetMs - Default reset timeout in ms (default: 60000)
 * @returns A configured CircuitBreaker instance
 */
export function createCircuitBreakerFromEnv(
  serviceName: string,
  defaultThreshold = 5,
  defaultResetMs = 60000,
): CircuitBreaker {
  const threshold = parseInt(
    process.env[CIRCUIT_BREAKER_ENV.SCRAPER_THRESHOLD] ??
      process.env[CIRCUIT_BREAKER_ENV.THRESHOLD] ??
      String(defaultThreshold),
    10,
  );

  const resetTimeoutMs = parseInt(
    process.env[CIRCUIT_BREAKER_ENV.SCRAPER_RESET_MS] ??
      process.env[CIRCUIT_BREAKER_ENV.RESET_MS] ??
      String(defaultResetMs),
    10,
  );

  return new CircuitBreaker({
    serviceName,
    threshold,
    resetTimeoutMs,
  });
}

